        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 56,
        marker = "***",
        depth = 3,
        instruction = "Predictions for the future have mixed accuracy, but are said to be more accurate if double-weather is predicted.",
